app.get("/api/calls/ice-config", rateLimit({ windowMs: 60000, max: 30, key: "call-ice-config" }), (_req, res) => {
  const iceServers = [
    { urls: "stun:stun.l.google.com:19302" },
    { urls: "stun:stun1.l.google.com:19302" },
    { urls: "stun:stun2.l.google.com:19302" },
  ];
  const turnUrls = String(process.env.WC_TURN_URLS || "").split(",").map((x) => x.trim()).filter(Boolean);
  const sharedSecret = String(process.env.WC_TURN_SHARED_SECRET || "");
  let turnConfigured = false;
  if (turnUrls.length && sharedSecret) {
    const expires = Math.floor(Date.now() / 1000) + 3600;
    const username = `${expires}:wrongchat`;
    const credential = crypto.createHmac("sha1", sharedSecret).update(username).digest("base64");
    iceServers.push({ urls: turnUrls, username, credential });
    turnConfigured = true;
  }
  res.setHeader("Cache-Control", "no-store");
  res.json({ ok: true, iceServers, turnConfigured });
});

